#include <bits/stdc++.h>
using namespace std;

#define size(v) ((int)(v).size())
typedef long long LL;

const int MOD = 1e9+7;
LL N; int K;

struct Matrix {
  int m[31][31];
  Matrix operator * (const Matrix &other) const {
    Matrix res = {0, };
    for (int i=0; i<=K; i++) {
      for (int j=0; j<=K; j++) {
        res.m[i][j] = 0;
        for (int k=0; k<=K; k++)
          res.m[i][j] = (res.m[i][j] + (LL)m[i][k] * other.m[k][j]) % MOD;
      }
    }
    return res;
  }
} A[65][30], P[65][30], S[65][30], R;

int main() {
  cin >> N >> K;
  vector<int> digits;
  for (; N; N /= K) digits.push_back(N % K);
  for (int i=0; i<K; i++) {
    for (int j=0; j<=K; j++) A[0][i].m[j][j] = 1;
    for (int j=0; j<=K; j++) A[0][i].m[i][j] = 1;
  }
  for (int i=1; i<(int)digits.size(); i++) {
    P[i-1][0] = A[i-1][0];
    for (int j=1; j<K; j++) P[i-1][j] = P[i-1][j-1] * A[i-1][j];
    S[i-1][K-1] = A[i-1][K-1];
    for (int j=K-1; j--;) S[i-1][j] = A[i-1][j] * S[i-1][j+1];
    for (int j=0; j<K; j++) {
      A[i][j] = S[i-1][j];
      if (j) A[i][j] = A[i][j] * P[i-1][j-1];
    }
  }
  int index=0;
  for (int i=0; i<=K; i++) R.m[i][i] = 1;
  for (int i=(int)digits.size(); i--;) {
    for (int j=0; j<digits[i]; j++) {
      R = R * A[i][index];
      index = (index+1)%K;
    }
  }
  int total_sum=0;
  for (int i=0; i<=K; i++) total_sum = (total_sum + R.m[i][K]) % MOD;
  cout << total_sum << endl;
}
